import pulp
import networkx as nx
import random

def gamma_t_ilp(G):
    prob = pulp.LpProblem('TDS', pulp.LpMinimize)
    nodes = list(G.nodes())
    x = {v: pulp.LpVariable(f'x_{v}', cat=pulp.LpBinary) for v in nodes}
    prob += pulp.lpSum(x.values())
    for v in nodes:
        prob += pulp.lpSum(x[u] for u in G.neighbors(v)) >= 1
    prob.solve(pulp.PULP_CBC_CMD(msg=False))
    return int(round(pulp.value(prob.objective)))

# Generate many graphs across diverse topologies
count = 0
for n in range(4, 30):
    for p in [0.05, 0.1, 0.15, 0.2, 0.3, 0.5]:
        for _ in range(20):
            G = nx.gnp_random_graph(n, p)
            if nx.is_connected(G):
                rad = nx.radius(G)
                gt = gamma_t_ilp(G)
                count += 1
                if rad > gt:
                    print(f'Counterexample GNP! n={n}, p={p}, rad={rad}, gt={gt}')
                    print(list(G.edges()))
                    exit(0)

# Barabasi-Albert
for n in range(10, 40):
